                FastVecScale_r4(&vec, &m->rot_row0, d->fA4);
                FastVecAdd_r4(&o->pos, &m->pos, &vec);
                FastVecScale_r4(&vec, &m->rot_row1, d->fA8);
                FastVecAdd_r4(&o->pos, &o->pos, &vec);
                FastVecScale_r4(&vec, &m->rot_row2, d->fAC);
                FastVecAdd_r4(&o->pos, &o->pos, &vec);
